INSERT INTO profession_details (profession_id, reality, pros, cons) VALUES
(76, 'Не "вдохновение каждый день". Это 50% правок сделай красивее, 30% брифы "а вдруг получится?", и 20% творчества. И дедлайны — вчера.', '["Творчество каждый день", "Можно работать из любой точки", "Портфолио = визитная карточка", "Нет потолка дохода (фриланс)"]', '["50% правок", "Клиенты не знают, что хотят", "Дедлайны — вчера", "Нестабильный доход", "Выгорание через 3-5 лет"]'),
(77, 'Не "звезда сцены". Это 90% репетиций, 5% выступлений, и 5% спасибо (редкость). И постоянная неуверенность: а вдруг я не талант?', '["Творчество — работа", "Эмоции — валюта", "Можно объехать мир", "Нет начальника (если фриланс)"]', '["90% репетиций, 10% выступлений", "Нестабильный доход", "Конкуренция огромная", "Выгорание + творческий кризис", "Здоровье: слух, голос, спина"]'),
(78, 'Не "роман за неделю". Это 80% правки, 10% пустой страницы, и 10% вдохновения. И дедлайны — вчера. И редактор: перепишите всё.', '["Свобода тем", "Можно работать из любой точки", "Каждый день новое", "Портфолио = визитная карточка"]', '["80% правки", "Пустая страница — страх", "Дедлайны — вчера", "Нестабильный доход", "Выгорание через 3-5 лет"]'),
(79, 'Не "звезда Голливуда". Это 90% прослушиваний (отказов), 5% репетиций, и 5% спасибо (редкость). И постоянная неуверенность.', '["Эмоции — валюта", "Можно объехать мир", "Нет начальника (если звезда)", "Каждый проект — новая жизнь"]', '["90% прослушиваний — отказ", "Нестабильный доход", "Конкуренция огромная", "Выгорание + кризис", "Здоровье: голос, спина, нервы"]'),
(80, 'Не "художник с камерой". Это 50% техники (свет, фокус, ISO), 30% общения с клиентом (а вдруг не так?), и 20% творчества. И 10 часов на ногах.', '["Творчество каждый день", "Можно работать из любой точки", "Каждый проект — новое", "Нет потолка дохода (фриланс)"]', '["50% техники, 30% клиенты", "10 часов на ногах", "Нестабильный доход", "Оборудование дорогое", "Выгорание через 5 лет"]'),
(81, 'Не "архитектор мечты". Это 60% согласований, 30% документации, и 10% "вот мой эскиз". И заказчик: а вдруг дешевле?', '["Виден результат — здание стоит", "Статус профессии", "Можно оставить след в городе", "Зарплата растёт с опытом"]', '["60% согласований", "Заказчик: а вдруг дешевле?", "Ответственность — безопасность", "Проекты годами", "Выгорание через 10 лет"]'),
(82, 'Не "танец под луной". Это 80% репетиций в зале, 15% травм, и 5% "аплодисменты". И возраст — 35+ уже ветеран.', '["Тело — инструмент", "Эмоции через движение", "Можно объехать мир", "Нет начальника (если солист)"]', '["80% репетиций", "Травмы — норма", "Возраст: 35+ ветеран", "Конкуренция огромная", "Карьера короткая"]'),
(83, 'Не "Микеланджело". Это 70% грязи и пыли, 25% ожидания схватывания, и 5% "вот оно!"', '["Тактильность — работа руками", "Виден результат — веками", "Медитация через материал", "Можно свой мастер-класс"]', '["70% грязи и пыли", "Материалы дорогие", "Заказы нерегулярные", "Физический труд", "Зарплата на старте низкая"]'),
(84, 'Не "ювелир из рекламы". Это 80% микроскопа и тисков, 15% "камень треснул", и 5% "блеск идеален".', '["Точность — гордость", "Виден результат — веками", "Статус профессии", "Можно свой салон"]', '["80% микроскопа", "Глаза устают", "Камни дорогие — риск", "Зарплата на старте низкая", "Конкуренция с заводами"]'),
(85, 'Не "художник кожи". Это 60% консультаций (а больно?), 30% стерильности, и 10% "шедевр на теле".', '["Эстетика + эмпатия", "Виден результат — навсегда", "Свобода творчества", "Можно свой салон"]', '["60% консультаций", "Клиенты в панике", "Стерильность — стресс", "Зрение падает", "Юридические риски"]'),
(86, 'Не "игра целый день". Это 50% Excel и баланса, 30% "игроки ненавидят", и 20% "вот оно — веселье!".', '["Создаёшь миры", "Игры — индустрия №1", "Креатив + логика", "Можно удалённо"]', '["50% Excel, не креатив", "Игроки токсичные", "Кранч — норма", "Выгорание через 3 года", "Проекты закрываются"]'),
(87, 'Не "DJ в клубе". Это 70% настройки оборудования, 20% "звук говно", и 10% "вот этот момент!".', '["Звук — валюта", "Можно объехать мир", "Нет начальника", "Каждый сет — уникален"]', '["70% настройки", "Уши устают", "Ночная жизнь — здоровье", "Нестабильный доход", "Оборудование дорогое"]'),
(88, 'Не "пиксельный волшебник". Это 60% ретопологии, 30% "клиент передумал", и 10% "рендер готов!".', '["Создаёшь миры из ничего", "Востребовано в кино/играх", "Можно удалённо", "Зарплата растёт быстро"]', '["60% ретопологии — рутина", "Рендеры по ночам", "Кранч — норма", "Выгорание через 3 года", "Глаза устают"]'),
(89, 'Не "красивые кнопочки". Это 50% исследований (а что пользователь думает?), 30% "стейкхолдер передумал", и 20% "вот оно — интуитивно!".', '["Эмпатия + логика + эстетика", "Востребовано везде", "Зарплата растёт быстро", "Можно удалённо"]', '["50% исследований", "Все дизайнеры критики", "Стейкхолдеры не знают, что хотят", "Выгорание через 3 года", "Тренды меняются быстро"]'),
(90, 'Не "взрывы в кино". Это 70% трекинга, 20% "рендер упал", и 10% "вот этот кадр!".', '["Кино — магия", "Востребовано везде", "Техника + креатив", "Зарплата растёт быстро"]', '["70% трекинга — рутина", "Рендеры по ночам", "Кранч — норма", "Выгорание через 3 года", "Программы дорогие"]'),
(91, 'Не "рисование в детстве". Это 60% правок "не то", 30% "а вдруг в другом стиле?", и 10% "вот оно!".', '["Визуальный рассказ", "Можно работать из любой точки", "Портфолио = всё", "Нет потолка дохода"]', '["60% правок", "Клиенты не знают, что хотят", "Дедлайны — вчера", "Нестабильный доход", "Выгорание через 3-5 лет"]'),
(92, 'Не "мастер из музея". Это 80% химии и микроскопа, 15% "краска осыпается", и 5% "вот оно — как новое!".', '["Спасаешь историю", "Виден результат — веками", "Терпение = мастерство", "Редкая профессия"]', '["80% химии", "Материалы дорогие", "Зарплата низкая", "Работа медленная", "Мало вакансий"]'),
(93, 'Не "цветы каждый день". Это 50% сезонности, 30% "розы подорожали", и 20% "вот этот букет!".', '["Природа + эстетика", "Виден результат — сразу", "Можно свой салон", "Творчество каждый день"]', '["50% сезонность", "Цветы портятся", "Физический труд", "Зарплата на старте низкая", "Работа в праздники"]'),
(94, 'Не "шеф из Netflix". Это 70% управления, 20% "критик ненавидит", и 10% "мишленовская звезда".', '["Вкус — валюта", "Статус, уважение", "Можно свой ресторан", "Творчество каждый день"]', '["70% управления", "Критики ненавидят", "Давление, кранч", "Выгорание через 5 лет", "Работа ночью, выходные"]'),
(95, 'Не "кофе и разговоры". Это 60% рутины (молоко, температура, чистка), 30% "клиент недоволен", и 10% "вот этот эспрессо!".', '["Вкус — мастерство", "Общение каждый день", "Можно свой кофейня", "Атмосфера = работа"]', '["60% рутины", "Ноги устают", "Зарплата на старте низкая", "Работа рано/поздно", "Выгорание через 3 года"]'),
(96, 'Не "праздник каждый день". Это 70% логистики, 20% "цветы завяли", и 10% "вот этот декор!".', '["Креатив + организация", "Виден результат — сразу", "Можно своё агентство", "Каждый проект — новое"]', '["70% логистики", "Цветы завяли — паника", "Клиенты в стрессе", "Выходные = работа", "Выгорание через 3 года"]'),
(97, 'Не "смешно каждый день". Это 80% написания, 15% "зал молчит", и 5% "аплодисменты!".', '["Смех — валюта", "Можно объехать мир", "Нет начальника", "Каждый выход — уникален"]', '["80% написания", "Зал молчит — ад", "Нестабильный доход", "Конкуренция огромная", "Выгорание + депрессия"]);
